mapper.update:
UPDATE anomaly_events
SET guardian_notified_at = #{notifiedAt}
WHERE user_id = #{userId}
  AND anomaly_event_id = #{anomalyEventId}
  AND risk_level = 'HIGH'
  AND final_action IS NULL
  AND guardian_notified_at IS NULL
